import{_ as e,o as s,c as d,a5 as i}from"./chunks/framework.CXroN2RO.js";const g=JSON.parse('{"title":"設計判断の読み進め方","description":"","frontmatter":{"title":"設計判断の読み進め方","study":{"source":"C++ Wiki","status":"published","summary":"「いつ・何を根拠に選ぶか」を、設計判断の各項目から学ぶための案内です。Yes/Noの二分ではなく、判断材料・例外・トレードオフを比べます。実際の判断で迷ったときには、下の一覧から必要な本文へ進めます。","section":"learning","format":"path","domain":"design","collection":"cpp-design","order":12}},"headers":[],"relativePath":"design/decisions/index.md","filePath":"design/decisions/index.md"}'),a={name:"design/decisions/index.md"};function r(n,t,o,l,c,h){return s(),d("div",null,[...t[0]||(t[0]=[i('<div id="第12部-判断ガイド" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="設計判断の読み進め方" tabindex="-1">設計判断の読み進め方 <a class="header-anchor" href="#設計判断の読み進め方" aria-label="Permalink to &quot;設計判断の読み進め方&quot;">​</a></h1><p>「<strong>いつ・何を根拠に選ぶか</strong>」を、設計判断の各項目から学ぶための案内です。Yes/Noの二分ではなく、<strong>判断材料・例外・トレードオフ</strong>を比べます。実際の判断で迷ったときには、下の一覧から必要な本文へ進めます。</p><h2 id="ページ一覧" tabindex="-1">ページ一覧 <a class="header-anchor" href="#ページ一覧" aria-label="Permalink to &quot;ページ一覧&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ページ</th><th>扱う判断</th></tr></thead><tbody><tr><td><a href="/study/design/decisions/split-class.html">クラスを分けるべきか</a></td><td>分割の基準と、分割しすぎの見分け方</td></tr><tr><td><a href="/study/design/decisions/create-interface.html">インターフェースを作るべきか</a></td><td>抽象を挟む価値の判定</td></tr><tr><td><a href="/study/design/decisions/inheritance-or-composition.html">継承かコンポジションか</a></td><td>is-a検証と実務フロー</td></tr><tr><td><a href="/study/design/decisions/abstraction-and-patterns.html">抽象化すべきか・デザインパターンを使うべきか</a></td><td>「3回ルール」と破綻シグナル</td></tr><tr><td><a href="/study/design/decisions/events-di-singleton.html">イベント・依存性注入・Singleton の判断</a></td><td>通知と依存配りの選択</td></tr><tr><td><a href="/study/design/decisions/cpp-choices.html">C++の選択(テンプレートか仮想関数か/値渡しか参照渡しか/unique_ptrかshared_ptrか/配列かvectorか/構造体かクラスか)</a></td><td>C++固有の5大選択</td></tr><tr><td><a href="/study/design/decisions/optimize-or-refactor.html">最適化すべきか・リファクタリングすべきか</a></td><td>投資判断としての改善</td></tr></tbody></table><p>仕上げに <a href="/study/design/decisions/exercises.html">演習</a>。</p><h2 id="全判断に共通する3原則" tabindex="-1">全判断に共通する3原則 <a class="header-anchor" href="#全判断に共通する3原則" aria-label="Permalink to &quot;全判断に共通する3原則&quot;">​</a></h2><ol><li><strong>可逆性で仕分ける</strong>: 後から安く変えられる決定は素朴に倒す(<a href="/study/design/foundations/yagni-kiss-dry.html">YAGNI</a>)。変えるのが高い決定(セーブ形式、公開API、データレイアウト)だけ先に考える</li><li><strong>証拠を要求する</strong>: 「いつか必要かも」ではなく「既に2回起きた」「計測で出た」を根拠にする</li><li><strong>選ばなかった案を書き残す</strong>: 判断はチームの共有財産。「なぜswitchのままにしたか」の一行コメントが将来の再判断を安くする</li></ol><hr><p><a href="/study/guide/cpp-index.html">全体目次</a> | 次: <a href="/study/design/decisions/split-class.html">クラスを分けるべきか</a></p>',10)])])}const p=e(a,[["render",r]]);export{g as __pageData,p as default};
